-- When trust with Tunde is high enough, open a DJ intro opportunity
create or replace function public.naad_refresh_opportunities()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_player uuid := auth.uid();
    v_tunde uuid := 'e1111111-1111-1111-1111-111111111101';
    v_trust int;
    v_id uuid;
begin
    if v_player is null then
        return jsonb_build_object('success', false, 'errorCode', 'UNAUTHENTICATED');
    end if;

    select trust into v_trust from public.relationships
    where subject_id = v_player and target_id = v_tunde;

    if coalesce(v_trust, 0) >= 55 then
        if not exists (
            select 1 from public.opportunities
            where player_id = v_player and opportunity_type = 'INTRO'
              and status = 'OPEN'
              and payload->>'from' = 'Tunde'
        ) then
            insert into public.opportunities (
                player_id, source_npc_id, opportunity_type, title, description, payload
            ) values (
                v_player, v_tunde, 'INTRO',
                'Meet the DJ',
                'Tunde can introduce you to a DJ who needs a runner for Beach Party.',
                jsonb_build_object('from', 'Tunde', 'targetRole', 'DJ', 'eventHint', 'Beach Party')
            ) returning id into v_id;

            insert into public.domain_events (event_type, player_id, payload)
            values ('OPPORTUNITY_OPENED', v_player, jsonb_build_object('opportunityId', v_id, 'type', 'INTRO'));
        end if;
    end if;

    return jsonb_build_object(
        'success', true,
        'opportunities', coalesce((
            select jsonb_agg(to_jsonb(o.*) order by o.created_at desc)
            from public.opportunities o
            where o.player_id = v_player and o.status = 'OPEN'
        ), '[]'::jsonb)
    );
end;
$$;

revoke all on function public.naad_refresh_opportunities() from public;
grant execute on function public.naad_refresh_opportunities() to authenticated;

create or replace function public.naad_accept_opportunity(p_request_id text, p_opportunity_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_player uuid := auth.uid();
    v_opp public.opportunities%rowtype;
begin
    if v_player is null then
        return jsonb_build_object('success', false, 'errorCode', 'UNAUTHENTICATED');
    end if;

    select * into v_opp from public.opportunities
    where id = p_opportunity_id and player_id = v_player and status = 'OPEN';
    if not found then
        return jsonb_build_object('success', false, 'errorCode', 'OPPORTUNITY_NOT_FOUND');
    end if;

    update public.opportunities set status = 'ACCEPTED' where id = p_opportunity_id;

    -- Small reputation-adjacent relationship bump with source NPC
    if v_opp.source_npc_id is not null then
        perform public.naad_apply_relationship_delta(
            p_request_id || ':rel', v_opp.source_npc_id, 2, 3, 0, 1, 0, 'Accepted opportunity'
        );
    end if;

    insert into public.domain_events (event_type, player_id, request_id, payload)
    values ('OPPORTUNITY_ACCEPTED', v_player, p_request_id,
        jsonb_build_object('opportunityId', p_opportunity_id, 'type', v_opp.opportunity_type));

    return jsonb_build_object('requestId', p_request_id, 'success', true,
        'payload', jsonb_build_object('opportunityId', p_opportunity_id, 'title', v_opp.title));
end;
$$;

revoke all on function public.naad_accept_opportunity(text, uuid) from public;
grant execute on function public.naad_accept_opportunity(text, uuid) to authenticated;

-- ===========================================================================
-- GATE 20 — World reactivity
-- ===========================================================================
create or replace function public.naad_react_to_event_attendance(p_event_id uuid, p_attendance integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_ev public.world_events%rowtype;
    v_traffic int;
    v_night int;
begin
    select * into v_ev from public.world_events where id = p_event_id;
    if not found then return; end if;

    -- More attendance → higher nightlife + traffic pressure
    v_night := least(100, 50 + p_attendance * 5);
    v_traffic := least(100, 40 + p_attendance * 4);

    update public.world_state
    set nightlife_level = v_night,
        traffic_level = v_traffic
    where id = 1;

    insert into public.domain_events (event_type, player_id, payload)
    values (
        'WORLD_REACTIVITY',
        null,
        jsonb_build_object(
            'cause', 'EVENT_ATTENDANCE',
            'eventId', p_event_id,
            'eventName', v_ev.name,
            'attendance', p_attendance,
            'nightlifeLevel', v_night,
            'trafficLevel', v_traffic
        )
    );
end;
$$;

-- List room presence for a location (for local multiplayer view)
create or replace function public.naad_list_room_presence(p_location_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_room_id uuid;
begin
    if auth.uid() is null then
        return jsonb_build_object('success', false, 'errorCode', 'UNAUTHENTICATED');
    end if;

    select id into v_room_id from public.game_rooms
    where location_id = p_location_id and status in ('OPEN','FULL')
    order by updated_at desc limit 1;

    if v_room_id is null then
        return jsonb_build_object('success', true, 'roomId', null, 'members', '[]'::jsonb);
    end if;

    return jsonb_build_object(
        'success', true,
        'roomId', v_room_id,
        'members', coalesce((
            select jsonb_agg(jsonb_build_object(
                'playerId', player_id,
                'displayName', display_name,
                'pos', jsonb_build_object('x', pos_x, 'y', pos_y, 'z', pos_z),
                'rotY', rot_y,
                'animation', animation,
                'emote', emote
            ))
            from public.room_presence where room_id = v_room_id
        ), '[]'::jsonb)
    );
end;
$$;

revoke all on function public.naad_list_room_presence(uuid) from public;
grant execute on function public.naad_list_room_presence(uuid) to authenticated;

-- =========================================================================
-- 0009_execute_command_router.sql
-- =========================================================================

-- Phase A — Unified command router
-- Unity sends one mutation entry point: naad_execute_command(request_id, type, payload)
-- Dispatches to existing validated handlers. Reads stay on dedicated RPCs.

create or replace function public.naad_execute_command(
    p_request_id text,
    p_type text,
    p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_type text := upper(trim(coalesce(p_type, '')));
    v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
    if auth.uid() is null then
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'UNAUTHENTICATED',
            'errorMessage', 'Not authenticated'
        );
    end if;

    if p_request_id is null or length(trim(p_request_id)) = 0 then
        return jsonb_build_object(
            'success', false,
            'errorCode', 'INVALID_REQUEST',
            'errorMessage', 'request_id is required'
        );
    end if;

    if v_type = '' then
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'INVALID_REQUEST',
            'errorMessage', 'type is required'
        );
    end if;

    case v_type
        when 'TRAVEL' then
            return public.naad_travel(
                p_request_id,
                nullif(v_payload->>'toLocationId', '')::uuid
            );

        when 'SPEND' then
            return public.naad_spend(
                p_request_id,
                v_payload->>'sku',
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'BUY' then
            -- alias of spend / legacy buy
            if v_payload ? 'sku' then
                return public.naad_spend(
                    p_request_id,
                    v_payload->>'sku',
                    nullif(v_payload->>'locationId', '')::uuid
                );
            end if;
            return public.naad_buy(
                p_request_id,
                v_payload->>'itemSku',
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'START_NIGHT' then
            return public.naad_start_night(p_request_id);

        when 'COMPLETE_NIGHT' then
            return public.naad_complete_night(p_request_id);

        when 'PHONE_REPLY' then
            return public.naad_respond_message(
                p_request_id,
                nullif(v_payload->>'messageId', '')::uuid,
                v_payload->>'action'
            );

        when 'JOIN_ROOM' then
            return public.naad_join_room(
                p_request_id,
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'LEAVE_ROOM' then
            return public.naad_leave_room(p_request_id);

        when 'ATTEND_EVENT' then
            return public.naad_attend_event(
                p_request_id,
                nullif(v_payload->>'eventId', '')::uuid
            );

        when 'RELATIONSHIP_DELTA' then
            return public.naad_apply_relationship_delta(
                p_request_id,
                nullif(v_payload->>'targetId', '')::uuid,
                coalesce((v_payload->>'trust')::integer, 0),
                coalesce((v_payload->>'respect')::integer, 0),
                coalesce((v_payload->>'affection')::integer, 0),
                coalesce((v_payload->>'loyalty')::integer, 0),
                coalesce((v_payload->>'conflict')::integer, 0),
                v_payload->>'reason'
            );

        when 'SET_CAREER' then
            return public.naad_set_career(
                p_request_id,
                v_payload->>'careerId'
            );

        when 'ACCEPT_OPPORTUNITY' then
            return public.naad_accept_opportunity(
                p_request_id,
                nullif(v_payload->>'opportunityId', '')::uuid
            );

        when 'COMMIT_MEMORY' then
            return public.naad_commit_npc_memory(
                p_request_id,
                nullif(v_payload->>'npcId', '')::uuid,
                v_payload->>'memoryType',
                v_payload->>'summary',
                coalesce((v_payload->>'importance')::real, 0.5)
            );

        when 'SET_WORLD_PERIOD' then
            return public.naad_set_world_period(v_payload->>'period');

        else
            return jsonb_build_object(
                'requestId', p_request_id,
                'success', false,
                'errorCode', 'UNSUPPORTED_COMMAND',
                'errorMessage', format('Unknown command type: %s', v_type)
            );
    end case;
exception
    when others then
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'COMMAND_EXCEPTION',
            'errorMessage', SQLERRM
        );
end;
$$;

revoke all on function public.naad_execute_command(text, text, jsonb) from public;
grant execute on function public.naad_execute_command(text, text, jsonb) to authenticated;

comment on function public.naad_execute_command(text, text, jsonb) is
    'Phase A unified mutation entry. Reads remain on dedicated RPCs.';

-- =========================================================================
-- 0010_security_hardening.sql
-- =========================================================================

-- ===========================================================================
-- 0010 — Security hardening
--
-- Three defects found in the 2026-11-05 audit. Each is a trust-boundary
-- violation, not a feature change:
--
--   1. naad_spend / naad_buy trusted the client's p_location_id. A modified
--      client could buy a CLUB_TICKET or SUYA_PLATE while standing in the
--      Apartment by passing the venue id. The authoritative location is
--      public.player_locations and nothing else.
--
--   2. naad_react_to_event_attendance was SECURITY DEFINER with no auth.uid()
--      check and — unlike every sibling function — no REVOKE. PostgreSQL grants
--      EXECUTE to PUBLIC by default, so it was callable with the anon key and
--      rewrote world_state.nightlife_level / traffic_level for all players.
--      It has zero callers in the codebase, so it is revoked outright.
--
--   3. naad_ensure_relationship was missing the REVOKE/GRANT pair every other
--      client-facing function has, leaving it executable by anon.
--
-- Deliberately NOT changed here (tracked in docs/IMPLEMENTATION_PLAN_REMAINING.md):
--   - command_receipts is still keyed on request_id alone, not (player_id,
--     request_id). Widening the PK is a data migration and needs its own pass.
--   - SET_WORLD_PERIOD is still dispatchable through the router by any
--     authenticated user; closing that needs an admin/role concept first.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. naad_spend — derive the location from player_locations, never the client
-- ---------------------------------------------------------------------------
create or replace function public.naad_spend(
    p_request_id text,
    p_sku text,
    p_location_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_player uuid := auth.uid();
    v_price public.price_list%rowtype;
    v_loc_type text;
    v_balance bigint;
    v_receipt public.command_receipts%rowtype;
    v_payload jsonb;
begin
    if v_player is null then
        return jsonb_build_object('requestId', p_request_id, 'success', false, 'errorCode', 'UNAUTHENTICATED');
    end if;
    if p_request_id is null or length(trim(p_request_id)) = 0 then
        return jsonb_build_object('success', false, 'errorCode', 'INVALID_REQUEST');
    end if;

    select * into v_receipt from public.command_receipts
     where request_id = p_request_id and player_id = v_player;
    if found then
        return jsonb_build_object(
            'requestId', v_receipt.request_id, 'success', v_receipt.success,
            'errorCode', v_receipt.error_code, 'errorMessage', v_receipt.error_message,
            'payload', v_receipt.result_payload
        );
    end if;

    select * into v_price from public.price_list where sku = p_sku;
    if not found then
        return jsonb_build_object('requestId', p_request_id, 'success', false, 'errorCode', 'SKU_NOT_FOUND');
    end if;

    -- Trust boundary: p_location_id is accepted for wire compatibility but is
    -- never used for authorisation. The server's own record wins.
    if v_price.location_type is not null then
        select l.type
          into v_loc_type
          from public.player_locations pl
          join public.locations l on l.id = pl.location_id
         where pl.player_id = v_player;

        if v_loc_type is null then
            insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
            values (p_request_id, v_player, 'SPEND', false, 'NO_LOCATION', 'Player location is unknown');
            return jsonb_build_object('requestId', p_request_id, 'success', false,
                'errorCode', 'NO_LOCATION', 'errorMessage', 'Player location is unknown');
        end if;

        if v_loc_type is distinct from v_price.location_type then
            insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
            values (p_request_id, v_player, 'SPEND', false, 'WRONG_LOCATION', 'Wrong location for this purchase');
            return jsonb_build_object('requestId', p_request_id, 'success', false,
                'errorCode', 'WRONG_LOCATION', 'errorMessage', 'Wrong location for this purchase');
        end if;
    end if;

    select balance into v_balance from public.wallets where player_id = v_player for update;
    if v_balance is null then
        return jsonb_build_object('requestId', p_request_id, 'success', false, 'errorCode', 'NO_WALLET');
    end if;
    if v_balance < v_price.price_ngn then
        insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
        values (p_request_id, v_player, 'SPEND', false, 'INSUFFICIENT_FUNDS', 'Not enough NGN');
        return jsonb_build_object('requestId', p_request_id, 'success', false,
            'errorCode', 'INSUFFICIENT_FUNDS', 'errorMessage', 'Not enough NGN');
    end if;

    update public.wallets
    set balance = balance - v_price.price_ngn, updated_at = now()
    where player_id = v_player;

    insert into public.wallet_transactions (player_id, type, amount, currency, reason, request_id)
    values (v_player, 'SPEND', v_price.price_ngn, 'NGN', p_sku, p_request_id);

    v_payload := jsonb_build_object(
        'sku', p_sku,
        'amount', v_price.price_ngn,
        'balanceAfter', v_balance - v_price.price_ngn,
        'category', v_price.category
    );

    insert into public.domain_events (event_type, player_id, request_id, payload)
    values ('MONEY_SPENT', v_player, p_request_id, v_payload);

    insert into public.command_receipts (request_id, player_id, command_type, success, result_payload)
    values (p_request_id, v_player, 'SPEND', true, v_payload);

    return jsonb_build_object('requestId', p_request_id, 'success', true, 'payload', v_payload);
end;
$$;

revoke all on function public.naad_spend(text, text, uuid) from public;
grant execute on function public.naad_spend(text, text, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. naad_buy — same rule; the hard-coded Suya Spot uuid was itself client-trusted
-- ---------------------------------------------------------------------------
create or replace function public.naad_buy(
    p_request_id text,
    p_item_sku text,
    p_location_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_player_id uuid := auth.uid();
    v_item public.items%rowtype;
    v_balance bigint;
    v_receipt public.command_receipts%rowtype;
    v_payload jsonb;
    v_loc_type text;
begin
    if v_player_id is null then
        return jsonb_build_object('requestId', p_request_id, 'success', false,
            'errorCode', 'UNAUTHENTICATED');
    end if;

    if p_request_id is null or length(trim(p_request_id)) = 0 then
        return jsonb_build_object('success', false, 'errorCode', 'INVALID_REQUEST');
    end if;

    select * into v_receipt from public.command_receipts
     where request_id = p_request_id and player_id = v_player_id;
    if found then
        return jsonb_build_object(
            'requestId', v_receipt.request_id,
            'success', v_receipt.success,
            'errorCode', v_receipt.error_code,
            'errorMessage', v_receipt.error_message,
            'payload', v_receipt.result_payload
        );
    end if;

    select * into v_item from public.items where sku = p_item_sku;
    if not found then
        insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
        values (p_request_id, v_player_id, 'BUY', false, 'ITEM_NOT_FOUND', 'Unknown item SKU');
        return jsonb_build_object('requestId', p_request_id, 'success', false,
            'errorCode', 'ITEM_NOT_FOUND');
    end if;

    -- Suya must be bought at the Suya Spot. Read the SERVER's record of where
    -- the player is; p_location_id is only a hint.
    if p_item_sku = 'SUYA_PLATE' then
        select l.type
          into v_loc_type
          from public.player_locations pl
          join public.locations l on l.id = pl.location_id
         where pl.player_id = v_player_id;

        if v_loc_type is distinct from 'SUYA_SPOT' then
            insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
            values (p_request_id, v_player_id, 'BUY', false, 'WRONG_LOCATION', 'Buy suya at the Suya Spot');
            return jsonb_build_object('requestId', p_request_id, 'success', false,
                'errorCode', 'WRONG_LOCATION', 'errorMessage', 'Buy suya at the Suya Spot');
        end if;
    end if;

    select balance into v_balance from public.wallets where player_id = v_player_id for update;
    if v_balance is null then
        return jsonb_build_object('requestId', p_request_id, 'success', false,
            'errorCode', 'NO_WALLET');
    end if;

    if v_balance < v_item.base_price_ngn then
        insert into public.command_receipts (request_id, player_id, command_type, success, error_code, error_message)
        values (p_request_id, v_player_id, 'BUY', false, 'INSUFFICIENT_FUNDS', 'Not enough NGN');
        return jsonb_build_object('requestId', p_request_id, 'success', false,
            'errorCode', 'INSUFFICIENT_FUNDS', 'errorMessage', 'Not enough NGN');
    end if;

    update public.wallets
    set balance = balance - v_item.base_price_ngn, updated_at = now()
    where player_id = v_player_id;

    insert into public.wallet_transactions (
        player_id, type, amount, currency, reason, related_entity_type, related_entity_id, request_id
    ) values (
        v_player_id, 'SPEND', v_item.base_price_ngn, 'NGN', p_item_sku, 'ITEM', v_item.id, p_request_id
    );

    v_payload := jsonb_build_object(
        'sku', v_item.sku,
        'amount', v_item.base_price_ngn,
        'balanceAfter', v_balance - v_item.base_price_ngn
    );

    insert into public.domain_events (event_type, player_id, request_id, payload)
    values ('ITEM_PURCHASED', v_player_id, p_request_id, v_payload);

    insert into public.command_receipts (
        request_id, player_id, command_type, success, result_payload
    ) values (p_request_id, v_player_id, 'BUY', true, v_payload);

    return jsonb_build_object(
        'requestId', p_request_id,
        'success', true,
        'payload', v_payload
    );
end;
$$;

revoke all on function public.naad_buy(text, text, uuid) from public;
grant execute on function public.naad_buy(text, text, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. naad_react_to_event_attendance — was PUBLIC-executable, wrote global state
--
-- No client or server code calls this. Revoking EXECUTE from every role that
-- the Data API can assume removes the write path; service_role keeps it for
-- any future server-side simulation work.
-- ---------------------------------------------------------------------------
revoke all on function public.naad_react_to_event_attendance(uuid, integer) from public;
revoke all on function public.naad_react_to_event_attendance(uuid, integer) from anon;
revoke all on function public.naad_react_to_event_attendance(uuid, integer) from authenticated;
grant execute on function public.naad_react_to_event_attendance(uuid, integer) to service_role;

-- Defensive: even if the grant above is later widened, an api-role caller is
-- rejected inside the function.
create or replace function public.naad_react_to_event_attendance(p_event_id uuid, p_attendance integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_ev public.world_events%rowtype;
    v_traffic int;
    v_night int;
    v_role text;
begin
    -- PostgREST/Supabase expose the JWT payload as `request.jwt.claims` (JSON).
    -- Direct SQL (migrations, psql, service jobs) has no claim set -> NULL ->
    -- allowed. Only an api JWT carries a role we must police.
    begin
        v_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
    exception when others then
        v_role := null;  -- unparseable/absent claims: treat as direct SQL
    end;

    if v_role is not null and v_role <> 'service_role' then
        raise exception 'naad_react_to_event_attendance is server-internal'
            using errcode = '42501';
    end if;

    select * into v_ev from public.world_events where id = p_event_id;
    if not found then return; end if;

    -- More attendance → higher nightlife + traffic pressure
    v_night := least(100, 50 + p_attendance * 5);
    v_traffic := least(100, 40 + p_attendance * 4);

    update public.world_state
    set nightlife_level = v_night,
        traffic_level = v_traffic
    where id = 1;

    insert into public.domain_events (event_type, player_id, payload)
    values (
        'WORLD_REACTIVITY',
        null,
        jsonb_build_object(
            'cause', 'EVENT_ATTENDANCE',
            'eventId', p_event_id,
            'eventName', v_ev.name,
            'attendance', p_attendance,
            'nightlifeLevel', v_night,
            'trafficLevel', v_traffic
        )
    );
end;
$$;

revoke all on function public.naad_react_to_event_attendance(uuid, integer) from public;
revoke all on function public.naad_react_to_event_attendance(uuid, integer) from anon;
revoke all on function public.naad_react_to_event_attendance(uuid, integer) from authenticated;
grant execute on function public.naad_react_to_event_attendance(uuid, integer) to service_role;

-- ---------------------------------------------------------------------------
-- 4. naad_ensure_relationship — restore the REVOKE/GRANT convention
-- ---------------------------------------------------------------------------
revoke all on function public.naad_ensure_relationship(uuid) from public;
revoke all on function public.naad_ensure_relationship(uuid) from anon;
grant execute on function public.naad_ensure_relationship(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. Belt and braces — no role other than service_role may write tables
--    directly. Today this holds only because RLS has no write policies; pinning
--    it means a future permissive policy cannot silently open a table.
-- ---------------------------------------------------------------------------
do $$
declare
    r record;
begin
    for r in
        select tablename
          from pg_tables
         where schemaname = 'public'
           and tablename <> 'players'   -- players has an intentional insert/update-own policy
    loop
        execute format('revoke insert, update, delete on public.%I from anon, authenticated', r.tablename);
    end loop;
end;
$$;

-- =========================================================================
-- 0011_hardening_errors_and_grants.sql
-- =========================================================================

-- ===========================================================================
-- 0011 — Security hardening, part 2
--
-- Follow-up to 0010. Each function body below was produced by transforming the
-- existing definition in place (not retyped), so the only differences are the
-- ones called out in the comments.
--
--   1. naad_execute_command leaked SQLERRM to the client on any exception,
--      which exposes constraint, table and column names. It now returns a
--      stable code and logs the detail server-side with RAISE WARNING.
--      A unique_violation on request_id gets its own DUPLICATE_REQUEST code
--      instead of an opaque COMMAND_EXCEPTION.
--
--   2. naad_get_world_clock derived minutesSinceMidnight from `extract(hour
--      from game_time)` (session TimeZone) while pinning the date to UTC. The
--      two disagree under any non-UTC session; both now use UTC explicitly.
--
--   3. players_update_own allowed any authenticated user to UPDATE every
--      mutable column of their own row, contradicting the comment on the
--      policy. Narrowed to column-level grants on display_name.
--
-- Still open (needs a staging database and its own migration):
--   - command_receipts is keyed on request_id alone. Lookups are now
--     player-scoped in every function touched by 0010/0011, so a foreign
--     request_id can no longer leak another player's payload, but the primary
--     key itself should become (player_id, request_id).
--   - SET_WORLD_PERIOD remains dispatchable through the router by any
--     authenticated user; closing that needs an admin/role concept.
--   - Six mutations accept p_request_id without persisting a receipt.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. naad_execute_command — stop leaking SQLERRM
-- ---------------------------------------------------------------------------
create or replace function public.naad_execute_command(
    p_request_id text,
    p_type text,
    p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_type text := upper(trim(coalesce(p_type, '')));
    v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
    if auth.uid() is null then
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'UNAUTHENTICATED',
            'errorMessage', 'Not authenticated'
        );
    end if;

    if p_request_id is null or length(trim(p_request_id)) = 0 then
        return jsonb_build_object(
            'success', false,
            'errorCode', 'INVALID_REQUEST',
            'errorMessage', 'request_id is required'
        );
    end if;

    if v_type = '' then
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'INVALID_REQUEST',
            'errorMessage', 'type is required'
        );
    end if;

    case v_type
        when 'TRAVEL' then
            return public.naad_travel(
                p_request_id,
                nullif(v_payload->>'toLocationId', '')::uuid
            );

        when 'SPEND' then
            return public.naad_spend(
                p_request_id,
                v_payload->>'sku',
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'BUY' then
            -- alias of spend / legacy buy
            if v_payload ? 'sku' then
                return public.naad_spend(
                    p_request_id,
                    v_payload->>'sku',
                    nullif(v_payload->>'locationId', '')::uuid
                );
            end if;
            return public.naad_buy(
                p_request_id,
                v_payload->>'itemSku',
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'START_NIGHT' then
            return public.naad_start_night(p_request_id);

        when 'COMPLETE_NIGHT' then
            return public.naad_complete_night(p_request_id);

        when 'PHONE_REPLY' then
            return public.naad_respond_message(
                p_request_id,
                nullif(v_payload->>'messageId', '')::uuid,
                v_payload->>'action'
            );

        when 'JOIN_ROOM' then
            return public.naad_join_room(
                p_request_id,
                nullif(v_payload->>'locationId', '')::uuid
            );

        when 'LEAVE_ROOM' then
            return public.naad_leave_room(p_request_id);

        when 'ATTEND_EVENT' then
            return public.naad_attend_event(
                p_request_id,
                nullif(v_payload->>'eventId', '')::uuid
            );

        when 'RELATIONSHIP_DELTA' then
            return public.naad_apply_relationship_delta(
                p_request_id,
                nullif(v_payload->>'targetId', '')::uuid,
                coalesce((v_payload->>'trust')::integer, 0),
                coalesce((v_payload->>'respect')::integer, 0),
                coalesce((v_payload->>'affection')::integer, 0),
                coalesce((v_payload->>'loyalty')::integer, 0),
                coalesce((v_payload->>'conflict')::integer, 0),
                v_payload->>'reason'
            );

        when 'SET_CAREER' then
            return public.naad_set_career(
                p_request_id,
                v_payload->>'careerId'
            );

        when 'ACCEPT_OPPORTUNITY' then
            return public.naad_accept_opportunity(
                p_request_id,
                nullif(v_payload->>'opportunityId', '')::uuid
            );

        when 'COMMIT_MEMORY' then
            return public.naad_commit_npc_memory(
                p_request_id,
                nullif(v_payload->>'npcId', '')::uuid,
                v_payload->>'memoryType',
                v_payload->>'summary',
                coalesce((v_payload->>'importance')::real, 0.5)
            );

        when 'SET_WORLD_PERIOD' then
            return public.naad_set_world_period(v_payload->>'period');

        else
            return jsonb_build_object(
                'requestId', p_request_id,
                'success', false,
                'errorCode', 'UNSUPPORTED_COMMAND',
                'errorMessage', format('Unknown command type: %s', v_type)
            );
    end case;
exception
    when unique_violation then
        -- request_id collided after the per-player receipt lookup missed it.
        -- Never surface the constraint name or any SQLERRM text to the client.
        raise warning 'naad_execute_command duplicate request_id: %', SQLERRM;
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'DUPLICATE_REQUEST',
            'errorMessage', 'Request already processed'
        );
    when others then
        raise warning 'naad_execute_command failed: %', SQLERRM;
        return jsonb_build_object(
            'requestId', p_request_id,
            'success', false,
            'errorCode', 'COMMAND_EXCEPTION',
            'errorMessage', 'Command failed'
        );
end;
$$;

revoke all on function public.naad_execute_command(text, text, jsonb) from public;
grant execute on function public.naad_execute_command(text, text, jsonb) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. naad_get_world_clock — UTC-consistent period derivation
-- ---------------------------------------------------------------------------
create or replace function public.naad_get_world_clock()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_row public.world_state%rowtype;
    v_minutes integer;
    v_period text;
    v_date text;
begin
    if auth.uid() is null then
        return jsonb_build_object(
            'success', false,
            'errorCode', 'UNAUTHENTICATED',
            'errorMessage', 'Not authenticated'
        );
    end if;

    select * into v_row from public.world_state where id = 1;
    if not found then
        return jsonb_build_object(
            'success', false,
            'errorCode', 'WORLD_MISSING',
            'errorMessage', 'world_state row missing'
        );
    end if;

    -- Derive minutes from the UTC wall clock. Previously `extract(hour ...)` used
    -- the session TimeZone while the date below was pinned to UTC, so the two
    -- disagreed under any non-UTC setting.
    v_minutes := (extract(hour from v_row.game_time at time zone 'UTC') * 60
                + extract(minute from v_row.game_time at time zone 'UTC'))::integer;
    v_period := public.naad_period_from_minutes(v_minutes);
    v_date := to_char(v_row.game_time at time zone 'UTC', 'YYYY-MM-DD');

    return jsonb_build_object(
        'success', true,
        'gameDate', v_date,
        'gameTime', v_row.game_time,
        'minutesSinceMidnight', v_minutes,
        'period', v_period,
        'timeScale', v_row.time_scale,
        'weather', v_row.weather,
        'trafficLevel', v_row.traffic_level,
        'nightlifeLevel', v_row.nightlife_level
    );
end;
$$;

revoke all on function public.naad_get_world_clock() from public;
grant execute on function public.naad_get_world_clock() to authenticated;

-- ---------------------------------------------------------------------------
-- 3. players — narrow the writable surface to display_name
--
-- The rows are already restricted to the caller by the players_update_own RLS
-- policy; this restricts the columns on top of that. All other player state is
-- written by SECURITY DEFINER RPCs, which run as the owner and are unaffected.
-- ---------------------------------------------------------------------------
revoke update on public.players from anon, authenticated;
grant update (display_name) on public.players to authenticated;
